// updateCapacity updates max length of metrics and resource attributes that will be used for the slice capacity.
func (mb *MetricsBuilder) updateCapacity(rm pmetric.ResourceMetrics) {
	if mb.metricsCapacity < rm.ScopeMetrics().At(0).Metrics().Len() {
		mb.metricsCapacity = rm.ScopeMetrics().At(0).Metrics().Len()
	}
}

// ResourceMetricsOption applies changes to provided resource metrics.
type ResourceMetricsOption interface {
	apply(pmetric.ResourceMetrics)
}

type resourceMetricsOptionFunc func(pmetric.ResourceMetrics)

func (rmof resourceMetricsOptionFunc) apply(rm pmetric.ResourceMetrics) {
	rmof(rm)
}

// WithResource sets the provided resource on the emitted ResourceMetrics.
// It's recommended to use ResourceBuilder to create the resource.
func WithResource(res pcommon.Resource) ResourceMetricsOption {
	return resourceMetricsOptionFunc(func(rm pmetric.ResourceMetrics) {
		res.CopyTo(rm.Resource())
	})
}

// WithStartTimeOverride overrides start time for all the resource metrics data points.
// This option should be only used if different start time has to be set on metrics coming from different resources.
func WithStartTimeOverride(start pcommon.Timestamp) ResourceMetricsOption {
	return resourceMetricsOptionFunc(func(rm pmetric.ResourceMetrics) {
		var dps pmetric.NumberDataPointSlice
		metrics := rm.ScopeMetrics().At(0).Metrics()
		for i := 0; i < metrics.Len(); i++ {
			switch metrics.At(i).Type() {
			case pmetric.MetricTypeGauge:
				dps = metrics.At(i).Gauge().DataPoints()
			case pmetric.MetricTypeSum:
				dps = metrics.At(i).Sum().DataPoints()
			}
			for j := 0; j < dps.Len(); j++ {
				dps.At(j).SetStartTimestamp(start)
			}
		}
	})
}

// EmitForResource saves all the generated metrics under a new resource and updates the internal state to be ready for
// recording another set of data points as part of another resource. This function can be helpful when one scraper
// needs to emit metrics from several resources. Otherwise calling this function is not required,
// just `Emit` function can be called instead.
// Resource attributes should be provided as ResourceMetricsOption arguments.
func (mb *MetricsBuilder) EmitForResource(options ...ResourceMetricsOption) {
	rm := pmetric.NewResourceMetrics()
	ils := rm.ScopeMetrics().AppendEmpty()
	ils.Scope().SetName(ScopeName)
	ils.Scope().SetVersion(mb.buildInfo.Version)
	ils.Metrics().EnsureCapacity(mb.metricsCapacity)
	mb.metricFscacheAcquireOk.emit(ils.Metrics())
	mb.metricFscacheAcquireOom.emit(ils.Metrics())
	mb.metricFscacheAcquireRequests.emit(ils.Metrics())
	mb.metricFscacheCookiesData.emit(ils.Metrics())
	mb.metricFscacheCookiesVolume.emit(ils.Metrics())
	mb.metricFscacheCookiesVolumeCollisions.emit(ils.Metrics())
	mb.metricFscacheCookiesVolumeOom.emit(ils.Metrics())
	mb.metricFscacheInvalidations.emit(ils.Metrics())
	mb.metricFscacheIoMisfit.emit(ils.Metrics())
	mb.metricFscacheIoRead.emit(ils.Metrics())
	mb.metricFscacheIoWrite.emit(ils.Metrics())
	mb.metricFscacheLruCount.emit(ils.Metrics())
	mb.metricFscacheLruDropped.emit(ils.Metrics())
	mb.metricFscacheLruExpired.emit(ils.Metrics())
	mb.metricFscacheLruRemoved.emit(ils.Metrics())
	mb.metricFscacheNospaceCreate.emit(ils.Metrics())
	mb.metricFscacheNospaceCull.emit(ils.Metrics())
	mb.metricFscacheNospaceWrite.emit(ils.Metrics())
	mb.metricFscacheRelinquishDrop.emit(ils.Metrics())
	mb.metricFscacheRelinquishRequests.emit(ils.Metrics())
	mb.metricFscacheRelinquishRetire.emit(ils.Metrics())
	mb.metricFscacheUpdatesRequests.emit(ils.Metrics())
	mb.metricFscacheUpdatesResize.emit(ils.Metrics())
	mb.metricFscacheUpdatesResizeSkipped.emit(ils.Metrics())
	mb.metricNetfsCacheReadDone.emit(ils.Metrics())
	mb.metricNetfsCacheReadFailed.emit(ils.Metrics())
	mb.metricNetfsCacheReadRequests.emit(ils.Metrics())
	mb.metricNetfsCacheWriteDone.emit(ils.Metrics())
	mb.metricNetfsCacheWriteFailed.emit(ils.Metrics())
	mb.metricNetfsCacheWriteRequests.emit(ils.Metrics())
	mb.metricNetfsDownloadDone.emit(ils.Metrics())
	mb.metricNetfsDownloadFailed.emit(ils.Metrics())
	mb.metricNetfsDownloadInstead.emit(ils.Metrics())
	mb.metricNetfsDownloadRequests.emit(ils.Metrics())
	mb.metricNetfsObjectsFolioQueue.emit(ils.Metrics())
	mb.metricNetfsObjectsReadReqs.emit(ils.Metrics())
	mb.metricNetfsObjectsSubreqs.emit(ils.Metrics())
	mb.metricNetfsObjectsWriteConflicts.emit(ils.Metrics())
	mb.metricNetfsReadsDirect.emit(ils.Metrics())
	mb.metricNetfsReadsFolio.emit(ils.Metrics())
	mb.metricNetfsReadsReadahead.emit(ils.Metrics())
	mb.metricNetfsReadsSingle.emit(ils.Metrics())
	mb.metricNetfsReadsWriteBegin.emit(ils.Metrics())
	mb.metricNetfsReadsWriteZskip.emit(ils.Metrics())
	mb.metricNetfsRetriesReadReq.emit(ils.Metrics())
	mb.metricNetfsRetriesReadSubreq.emit(ils.Metrics())
	mb.metricNetfsRetriesWriteReq.emit(ils.Metrics())
	mb.metricNetfsRetriesWriteSubreq.emit(ils.Metrics())
	mb.metricNetfsUploadDone.emit(ils.Metrics())
	mb.metricNetfsUploadFailed.emit(ils.Metrics())
	mb.metricNetfsUploadRequests.emit(ils.Metrics())
	mb.metricNetfsWblockSkip.emit(ils.Metrics())
	mb.metricNetfsWblockWait.emit(ils.Metrics())
	mb.metricNetfsWritesBuffered.emit(ils.Metrics())
	mb.metricNetfsWritesCopyToCache.emit(ils.Metrics())
	mb.metricNetfsWritesDirect.emit(ils.Metrics())
	mb.metricNetfsWritesPages.emit(ils.Metrics())
	mb.metricNetfsWritesWritethrough.emit(ils.Metrics())
	mb.metricNetfsZeroOpsShort.emit(ils.Metrics())
	mb.metricNetfsZeroOpsSkip.emit(ils.Metrics())
	mb.metricNetfsZeroOpsZero.emit(ils.Metrics())

	for _, op := range options {
		op.apply(rm)
	}

	if ils.Metrics().Len() > 0 {
		mb.updateCapacity(rm)
		rm.MoveTo(mb.metricsBuffer.ResourceMetrics().AppendEmpty())
	}
}

// Emit returns all the metrics accumulated by the metrics builder and updates the internal state to be ready for
// recording another set of metrics. This function will be responsible for applying all the transformations required to
// produce metric representation defined in metadata and user config, e.g. delta or cumulative.
func (mb *MetricsBuilder) Emit(options ...ResourceMetricsOption) pmetric.Metrics {
	mb.EmitForResource(options...)
	metrics := mb.metricsBuffer
	mb.metricsBuffer = pmetric.NewMetrics()
	return metrics
}

